import click
from click.testing import CliRunner

def test_auto_envvar_prefix_error_hint():
    @click.command(context_settings={"auto_envvar_prefix": "MYAPP"})
    @click.option("--port", type=int, required=True, show_envvar=True)
    def cli(port):
        click.echo(f"port={port}")

    runner = CliRunner()
    result = runner.invoke(cli, [])

    # The error output should contain the env var
    assert "Error: Missing option '--port' (env var: 'MYAPP_PORT')." in result.output

from __future__ import annotations
import inspect
from attrs import define

@define
class DoesNotWork:
    _foo: Foo

class Foo:
    pass

def test_forward_reference_annotation():
    # This should work, but currently raises NameError: name 'Foo' is not defined
    sig = inspect.signature(DoesNotWork, eval_str=True)
    assert 'foo' in sig.parameters
    assert sig.parameters['foo'].annotation == Foo
